import { test, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { testServer } from '../../server/test/helpers.js';
const execute = promisify(execFile);
let server, owner, project, sprint, config;
beforeEach(async () => {
  server = await testServer(); owner = server.agent();
  const signup = await owner('POST', '/auth/signup', { name: 'Planning CLI', email: 'planning@cli.test', password: 'correct-horse-battery' });
  const org = (await owner('POST', '/orgs', { name: 'Planning CLI' })).data.organization;
  project = (await owner('POST', '/orgs/' + org.id + '/projects', { key: 'PC', name: 'Planning CLI' })).data.project;
  sprint = (await owner('POST', '/projects/' + project.id + '/sprints', { name: 'Current cycle', startDate: '2026-10-01', endDate: '2026-10-20' })).data.sprint;
  config = path.join(server.ctx.config.dataDir, 'cli.json');
  await writeFile(config, JSON.stringify({ url: server.url, cookie: signup.cookie }), { mode: 0o600 });
});
afterEach(async () => server.close());
async function cli(args) {
  const result = await execute(process.execPath, [fileURLToPath(new URL('../bin/crew.js', import.meta.url)), ...args, '--config', config, '--json'], { timeout: 15000 });
  return JSON.parse(result.stdout);
}
test('actual planning CLI follows eligible candidate cursor pages and preserves scope command compatibility', async () => {
  const first = (await owner('POST', '/projects/' + project.id + '/issues', { title: 'Candidate first' })).data.issue;
  const second = (await owner('POST', '/projects/' + project.id + '/issues', { title: 'Candidate second' })).data.issue;
  const page = await cli(['sprint', 'candidates', sprint.id, '--q', 'Candidate', '--limit', '1']);
  assert.equal(page.items.length, 1); assert.ok(page.nextCursor);
  const next = await cli(['sprint', 'candidates', sprint.id, '--q', 'Candidate', '--limit', '1', '--cursor', page.nextCursor]);
  assert.deepEqual(new Set([page.items[0].id, next.items[0].id]), new Set([first.id, second.id]));
  await cli(['sprint', 'add', sprint.id, '--issues', first.id, '--revision', sprint.revision]);
  assert.equal((await cli(['sprint', 'scope', sprint.id])).issues[0].issueId, first.id);
  assert.equal((await cli(['sprint', 'scope-page', sprint.id, '--limit', '1'])).items[0].issueId, first.id);
});
test('actual planning CLI refuses stale sprint and project revisions without overwriting latest fields', async () => {
  await owner('PATCH', '/sprints/' + sprint.id, { goal: 'Remote goal' });
  await assert.rejects(() => cli(['sprint', 'update', sprint.id, '--name', 'Stale', '--revision', sprint.revision]), /resource changed/);
  assert.equal((await owner('GET', '/sprints/' + sprint.id)).data.sprint.goal, 'Remote goal');
  await owner('PATCH', '/projects/' + project.id, { name: 'Remote project' });
  await assert.rejects(() => cli(['project', 'update', project.id, '--name', 'Stale', '--revision', project.revision]), /resource changed/);
  assert.equal((await cli(['project', 'list', '--q', 'Remote project', '--limit', '1'])).items[0].id, project.id);
});

import { uploadAttachment, validateUpload } from './attachment-state.js';
export function createAttachmentQueue({ issueId, maxBytes, notify = () => {}, upload = uploadAttachment, onSaved = () => {} }) {
  let entries = [];
  let serial = 0;
  let running = false;
  let disposed = false;
  let paused = false;
  let controller = null;
  let generation = 0;
  const snapshot = () => ({ entries: entries.map(entry => ({ ...entry, attempts: [...entry.attempts] })), running, paused });
  function publish() { if (!disposed) notify(snapshot()); }
  function update(id, patch) { entries = entries.map(entry => entry.id === id ? { ...entry, ...patch } : entry); publish(); }
  function add(files) {
    if (disposed || running) return;
    entries = [...entries, ...Array.from(files, file => {
      const problem = validateUpload(file, maxBytes);
      return { id: ++serial, file, status: problem ? 'invalid' : 'pending', progress: null, result: null,
        error: problem ? new Error(problem) : null, attempts: [] };
    })];
    publish();
  }
  async function start() {
    if (disposed || running) return;
    running = true; paused = false; const ticket = ++generation; publish();
    try {
      for (const entry of entries) {
        if (disposed || paused || ticket !== generation) break;
        if (entry.status !== 'pending') continue;
        controller = new AbortController();
        const ownController = controller;
        update(entry.id, { status: 'uploading', error: null, progress: { loaded: 0, total: entry.file.size } });
        const startedAt = new Date().toISOString();
        try {
          const result = await upload({ issueId, file: entry.file, signal: ownController.signal,
            onProgress(progress) { if (!disposed && ticket === generation && !ownController.signal.aborted) update(entry.id, { progress }); } });
          if (disposed || ticket !== generation) break;
          if (ownController.signal.aborted) throw Object.assign(new Error('Upload cancelled; check saved attachments before retrying.'), { code: 'CANCELLED' });
          update(entry.id, { status: 'succeeded', result: result.attachment, attempts: [...entry.attempts, { startedAt, status: 'succeeded', attachmentId: result.attachment.id }] });
          onSaved(result.attachment);
        } catch (error) {
          if (disposed || ticket !== generation) break;
          if ([401, 403, 404].includes(error.status)) paused = true;
          const status = ownController.signal.aborted || error.code === 'CANCELLED' ? 'cancelled' : 'failed';
          update(entry.id, { status, error, attempts: [...entry.attempts, { startedAt, status, message: error.message }] });
        } finally { if (controller === ownController) controller = null; }
      }
    } finally { if (!disposed && ticket === generation) { running = false; publish(); } }
  }
  return { snapshot, add, start,
    cancel() { paused = true; controller?.abort(); publish(); },
    remove(id) { if (!running) { entries = entries.filter(entry => entry.id !== id); publish(); } },
    clearFinished() { if (!running) { entries = entries.filter(entry => ['pending', 'uploading'].includes(entry.status)); publish(); } },
    retry(id) {
      if (disposed || running) return;
      const entry = entries.find(value => value.id === id);
      if (entry && ['failed', 'cancelled'].includes(entry.status)) update(id, { status: 'pending', error: null, progress: null });
    },
    dispose() { disposed = true; paused = true; generation++; controller?.abort(); controller = null; }
  };
}

import { Page, Field, Button, Notice, Loading, useLoad } from '../../components/ui.jsx';
import { ProjectLinks, WorkflowEditor } from './projects.jsx';
import { RevisionDecision } from './issue-controls.jsx';
import { usePlanningAction, usePlanningDraft, PlanningRefresh } from './planning-controls.jsx';
import { workflowPayload } from './project-state.js';
import { WorkflowReview } from './workflow-review.jsx';
import { useState } from 'preact/hooks';
export function ProjectSettings(props) { return <SettingsResource key={props.params.projectId} {...props} />; }
function SettingsResource({ api, params, navigate }) {
  const route = '/projects/' + encodeURIComponent(params.projectId);
  const result = useLoad(() => api.get(route), [route]);
  const form = usePlanningDraft(result.data?.project);
  const action = usePlanningAction();
  const [impact, setImpact] = useState({ ready: false });
  const canManage = result.data?.permissions.manage && !result.error;
  const record = form.draft;
  async function inspect() {
    await action.run(() => api.get(route), value => form.setLatest(value.project));
  }
  function load(value) { form.load(value); action.setError(null); }
  async function save(event) {
    event.preventDefault();
    if (!canManage) return;
    if (!impact.ready || impact.draftKey !== JSON.stringify(record.statuses)) { action.setError(new Error("Review and resolve workflow impact before saving.")); return; }
    let statuses;
    try { statuses = workflowPayload(record.statuses); }
    catch (error) { action.setError(error); return; }
    await action.run(() => api.patch(route, { key: record.key, name: record.name, description: record.description,
      statuses, expectedRevision: form.base.revision }), value => {
      form.load(value.project); action.setNotice('Project and workflow saved'); result.reload();
    });
  }
  async function archive() {
    if (!canManage || !globalThis.confirm((record.archived ? 'Restore' : 'Archive') + ' this project? Unsaved fields remain local.')) return;
    await action.run(() => api.patch(route, { archived: !form.base.archived, expectedRevision: form.base.revision }), value => {
      form.setLatest(value.project); result.reload(); action.setNotice('Project lifecycle updated. Inspect the latest saved version.');
    });
  }
  async function remove() {
    if (!canManage || !globalThis.confirm('Delete this project and all its work? This cannot be undone.')) return;
    await action.run(() => api.delete(route, { expectedRevision: form.base.revision }), () => navigate('/projects'));
  }
  if (!record) return result.error ? <Notice error={result.error} /> : <Loading />;
  const problem = action.error ?? result.error;
  const latest = form.latest ?? problem?.details?.current;
  const staleError = problem ?? (latest ? new Error('Saved project settings changed. Your draft is retained.') : null);
  function update(field, value) { form.setDraft(previous => ({ ...previous, [field]: value })); }
  return <Page title={record.name + ' settings'}>
    <ProjectLinks projectId={record.id} />
    <PlanningRefresh busy={action.busy} dirty={form.dirty} onRefresh={result.reload} />
    <Notice>{action.notice}</Notice>
    <RevisionDecision error={staleError} latest={latest} busy={action.busy} onInspect={inspect} onLoad={load}
      onKeep={value => { if (globalThis.confirm('Use this saved revision as your new baseline while keeping all local fields?')) { form.keep(value); action.setError(null); } }} />
    {!canManage && <Notice>Project settings require current owner or administrator access. This draft remains visible and cannot be submitted.</Notice>}
    <form onSubmit={save} className="panel">
      <fieldset disabled={!canManage || action.busy}>
        <legend>Project details and workflow</legend>
        <Field label="Project key" name="key" value={record.key} onInput={event => update('key', event.currentTarget.value)} required maxLength={12} error={problem?.details?.key} />
        <Field label="Name" name="name" value={record.name} onInput={event => update('name', event.currentTarget.value)} required maxLength={160} error={problem?.details?.name} />
        <Field label="Description" error={problem?.details?.description}><textarea name="description" value={record.description} onInput={event => update('description', event.currentTarget.value)} rows={4} maxLength={20000} /></Field>
        <WorkflowEditor statuses={record.statuses} onChange={value => update('statuses', value)} />
        <WorkflowReview api={api} projectId={record.id} revision={form.base.revision} base={form.base.statuses} draft={record.statuses} onDecision={setImpact} />
        {Object.entries(problem?.details ?? {}).filter(([key]) => key.startsWith('statuses') || key === 'statusId').map(([key, value]) => <p role="alert" key={key}>{key}: {String(value)}</p>)}
        <Button type="submit" busy={action.busy} disabled={!form.dirty || !impact.ready || impact.draftKey !== JSON.stringify(record.statuses)}>Save project and workflow</Button>
      </fieldset>
    </form>
    <section className="panel"><h2>Project lifecycle</h2>
      <Button disabled={!canManage} busy={action.busy} onClick={archive}>{record.archived ? 'Restore project' : 'Archive project'}</Button>
      <Button disabled={!canManage} busy={action.busy} className="danger" onClick={remove}>Delete project</Button>
    </section>
  </Page>;
}

import { useEffect, useState } from 'preact/hooks';
import { Notice, Loading, Button, useLoad } from '../../components/ui.jsx';
import { reviewWorkflow } from './workflow-review.js';
export function WorkflowReview({ api, projectId, revision, base, draft, onDecision }) {
  const current = useLoad(() => api.get('/projects/' + projectId + '/workflow'), [projectId, revision]);
  const [accepted, setAccepted] = useState('');
  const review = reviewWorkflow(base, draft, current.data?.usage ?? []);
  const signature = JSON.stringify({ rows: review.rows, draft, revision: current.data?.project?.revision });
  const changed = current.data?.project?.revision !== revision;
  const ready = !current.loading && !current.error && !changed && !review.blocked && (!review.needsDecision || accepted === signature);
  useEffect(() => onDecision({ ready, review, draftKey: JSON.stringify(draft) }), [ready, signature]);
  return <section aria-label="Workflow impact review"><h2>Workflow impact</h2>
    <p>Existing status IDs remain stable through renames and reordering. Counts describe the current saved issues; category changes update completion semantics for those issues and their sprint history.</p>
    {current.loading && <Loading />}<Notice error={current.error} />
    {changed && !current.loading && <Notice>Current workflow usage changed. Refresh the planning view, inspect the latest project, and deliberately load or keep your draft on that revision.</Notice>}
    <div className="table-scroll"><table><thead><tr><th>Status and stable ID</th><th>Current issues</th><th>Draft impact</th></tr></thead><tbody>
      {review.rows.map(row => <tr key={row.id}><td>{row.name}<br /><small>{row.id}</small></td><td>{row.issueCount}</td><td>
        {row.removed ? row.issueCount ? 'Blocked: move these issues before removing this status' : 'Remove unused status' : row.recategorized ? row.previousCategory + ' → ' + row.nextCategory : row.nextName !== row.name ? 'Rename to ' + row.nextName : 'Preserve status'}
      </td></tr>)}
    </tbody></table></div>
    {review.errors.map((error, index) => <p key={index} role="alert">{error.index !== undefined ? 'Status ' + (error.index + 1) + ' ' : ''}{error.field}: {error.message}</p>)}
    {review.occupiedRemoval && <Notice>Removal is blocked while issues use this status. <a href={'#/projects/' + projectId + '/board'}>Open the board and use move or bulk status actions</a>, then refresh this draft.</Notice>}
    {review.needsDecision && <label><input type="checkbox" checked={accepted === signature} onChange={event => setAccepted(event.currentTarget.checked ? signature : '')} /> I reviewed these category changes and their current issue counts.</label>}
    <Button type="button" disabled={current.loading} onClick={current.reload}>Refresh workflow impact</Button>
  </section>;
}
